package fraymus.workspace;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class GameCost123Test {
 static JSONObject row(String strategy,int repeat,double seconds,int pickups,boolean won){var controller=new JSONObject().put("policy",GameStrategy123.policy(strategy)).put("pickups",pickups).put("damage",0).put("opportunity120",new JSONObject().put("waitStarts",0).put("revisitStarts",0));var m=new JSONObject().put("strategy",strategy).put("taskId",UUID.randomUUID().toString()).put("evidenceVerified",true).put("completionCertified",won).put("parameters",new JSONObject().put("seed",1)).put("final",new JSONObject().put("tick",600).put("player",new JSONObject().put("won",won).put("dead",!won)).put("controller",controller)).put("audit",new JSONObject().put("existingAI",won?"won":"failed").put("aiPickups",pickups).put("aiDamage",0).put("completionControl",GameStrategy123.policy(strategy)));return new JSONObject().put("case","fixture").put("repeat",repeat).put("strategy",strategy).put("wallNanos",(long)(seconds*1e9)).put("setupNanos",1).put("advanceNanos",1).put("verifyNanos",1).put("closeNanos",1).put("measurement",m);}
 static JSONObject comparison(JSONArray rows){return GameCost123.summarize(rows).getJSONArray("cases").getJSONObject(0).getJSONArray("comparisons").getJSONObject(0);}
 @Test public void conservativeBreakEvenUsesWorstObservedCostAndMinimumGain(){var rows=new JSONArray();for(int i=0;i<3;i++){rows.put(row("full",i,12+i,1,true));rows.put(row("no-return",i,10,0,true));}var c=comparison(rows);assertEquals(4,c.getDouble("observedConservativeSecondsPerExtraPickup"),0);assertEquals(3,c.getJSONObject("elapsedDeltaSeconds").getDouble("median"),0);}
 @Test public void timingNoiseDoesNotBecomeAClaimedSaving(){var rows=new JSONArray();for(int i=0;i<3;i++){rows.put(row("full",i,9+i,0,true));rows.put(row("no-return",i,10,0,true));}var c=comparison(rows);assertFalse(c.has("observedConservativeSecondsPerExtraPickup"));assertTrue(c.getString("assessment").contains("No additional"));}
 @Test public void sameOutcomeCanBeConsistentlyFaster(){var rows=new JSONArray();for(int i=0;i<3;i++){rows.put(row("full",i,8,1,true));rows.put(row("no-return",i,10,1,true));}assertTrue(comparison(rows).getString("assessment").contains("faster in every"));}
 @Test public void failedFinishRefusesEconomicRecommendationEvenWithMoreItems(){var rows=new JSONArray();for(int i=0;i<3;i++){rows.put(row("full",i,12,1,i!=2));rows.put(row("no-return",i,10,0,true));}var c=comparison(rows);assertFalse(c.getBoolean("safePairedFinishes"));assertFalse(c.has("observedConservativeSecondsPerExtraPickup"));}
 @Test public void incompleteAndUnboundTimingsAreRejected(){
  var a=row("full",0,12,1,true);var b=row("no-return",0,10,0,true);assertTrue(comparison(new JSONArray().put(a).put(b)).getString("assessment").contains("Insufficient"));
  assertThrows(IllegalArgumentException.class,()->GameCost123.summarize(new JSONArray().put(a).put(a)));
  var mismatch=WorldFrames.copy(b);mismatch.put("repeat",1);assertThrows(IllegalArgumentException.class,()->GameCost123.summarize(new JSONArray().put(a).put(mismatch)));
  for(String field:List.of("wallNanos","setupNanos","verifyNanos","closeNanos")){var bad=WorldFrames.copy(a).put(field,-1);assertThrows(IllegalArgumentException.class,()->GameCost123.summarize(new JSONArray().put(bad)));}
  var missing=WorldFrames.copy(a).put("wallNanos",1);assertThrows(IllegalArgumentException.class,()->GameCost123.summarize(new JSONArray().put(missing)));
  var geometry=WorldFrames.copy(b);geometry.getJSONObject("measurement").getJSONObject("parameters").put("seed",2);assertThrows(IllegalArgumentException.class,()->GameCost123.summarize(new JSONArray().put(a).put(geometry)));
  var label=WorldFrames.copy(a).put("strategy","direct");assertThrows(IllegalArgumentException.class,()->GameCost123.summarize(new JSONArray().put(label)));
 }
 @Test public void declaredCasesPassGeometryAdmission(){for(String partition:List.of("development","reserved"))for(String request:GamePickupStudy123Test.cases(partition).values())GameTask115.request("Create a playable Mario level "+request);}
 @Test public void explicitStrategiesAreBoundedAndDefaultIsPreserved(){String request="Create a playable Mario level goombaTile=24 ";assertEquals("full",GameTask115.request(request).getString("pickupStrategy"));for(String s:GameStrategy123.STRATEGIES)assertEquals(s,GameTask115.request(request+"pickupStrategy="+s).getString("pickupStrategy"));for(String bad:List.of("pickupStrategy=other","pickupStrategy=","pickupStrategy","pickupStrategy=full pickupStrategy=direct","pickupStrategy=full pickupStrategy"))assertThrows(bad,IllegalArgumentException.class,()->GameTask115.request(request+bad));assertThrows(IllegalArgumentException.class,()->GameTask115.request("Create a playable Mario level pickupStrategy=direct"));}
}
